  },
];

const form = document.getElementById('quiz-form');
const resultsSection = document.getElementById('results');
const resultsScore = document.getElementById('results-score');
const resultsList = document.getElementById('results-list');
const resetBtn = document.getElementById('reset-btn');

form.addEventListener('submit', (e) => {
  e.preventDefault();
  gradeQuiz();
});

resetBtn.addEventListener('click', resetQuiz);

function getSelectedValues(name) {
  return Array.from(
    form.querySelectorAll(`input[name="${name}"]:checked`)
  ).map((cb) => cb.value);
}

function gradeQuiz() {
  let correctCount = 0;

  QUESTIONS.forEach(({ name, correctValues }) => {
    const selected = getSelectedValues(name);
    const isFullyCorrect =
      selected.length === correctValues.length &&
      selected.every((v) => correctValues.includes(v));

    if (isFullyCorrect) correctCount++;

    // Annotate each option
    const options = form.querySelectorAll(`input[name="${name}"]`);
    options.forEach((input) => {
      const label = input.closest('.answer-option');
      const isCorrectAnswer = correctValues.includes(input.value);
      const wasSelected = input.checked;

      label.classList.remove('correct', 'incorrect', 'missed');

      if (wasSelected && isCorrectAnswer) {
        label.classList.add('correct');
      } else if (wasSelected && !isCorrectAnswer) {
        label.classList.add('incorrect');
      } else if (!wasSelected && isCorrectAnswer) {
        label.classList.add('missed');
      }

      input.disabled = true;
    });
  });

  showResults(correctCount);
}

function showResults(correctCount) {
  const total = QUESTIONS.length;
  resultsScore.textContent = `${correctCount} / ${total} correct`;

  const resultMessages = [
    {
      question: 'Q1 — Statically typed languages',
      correct: 'Java, TypeScript',
      note: 'Python and Ruby use dynamic typing.',
    },
    {
      question: 'Q2 — Systems programming languages',
      correct: 'Rust, C',
      note: 'JavaScript targets the web; SQL is a query language.',
    },
    {
      question: 'Q3 — First-class functions',
      correct: 'Haskell, JavaScript, Python',
      note: 'COBOL does not treat functions as first-class values.',
    },
  ];

  resultsList.innerHTML = '';
  resultMessages.forEach(({ question, correct, note }, i) => {
    const selected = getSelectedValues(QUESTIONS[i].name);
    const correctVals = QUESTIONS[i].correctValues;
    const ok =
      selected.length === correctVals.length &&
      selected.every((v) => correctVals.includes(v));

    const li = document.createElement('li');
    li.innerHTML = `
      <strong>${question}</strong><br>
      <span class="${ok ? 'tag-correct' : 'tag-incorrect'}">${ok ? '✓ Correct' : '✗ Incorrect'}</span>
      — Answer: ${correct}. <em>${note}</em>
    `;
    resultsList.appendChild(li);
  });

  form.querySelector('.submit-btn').disabled = true;
  resultsSection.hidden = false;
  resultsSection.scrollIntoView({ behavior: 'smooth', block: 'start' });
}

function resetQuiz() {
  // Re-enable and uncheck all inputs, clear visual state
  form.querySelectorAll('input[type="checkbox"]').forEach((cb) => {
    cb.checked = false;
    cb.disabled = false;
    cb.closest('.answer-option').classList.remove('correct', 'incorrect', 'missed');
  });

  form.querySelector('.submit-btn').disabled = false;
  resultsSection.hidden = true;
  resultsList.innerHTML = '';
  resultsScore.textContent = '';

  window.scrollTo({ top: 0, behavior: 'smooth' });
}
