+/* ── Reset & base ── */
+*, *::before, *::after {
+  box-sizing: border-box;
+  margin: 0;
+  padding: 0;
+}
+
+:root {
+  --bg:          #0d0f14;
+  --surface:     #161b25;
+  --surface-2:   #1e2535;
+  --border:      #2a3347;
+  --border-hover:#3d5080;
+  --accent:      #4f8ef7;
+  --accent-dim:  #1e3a6e;
+  --text:        #e2e8f0;
+  --text-muted:  #7a8aa8;
+  --text-label:  #a8b8d0;
+  --correct:     #34d399;
