+}
+
+.answer-option.correct .checkbox-custom {
+  background: var(--correct);
+  border-color: var(--correct);
+}
+
+.answer-option.correct .checkbox-custom::after {
+  opacity: 1;
+}
+
+.answer-option.incorrect {
+  background: #2e0d0d;
+  border-color: var(--incorrect);
+}
+
+.answer-option.incorrect .checkbox-custom {
+  background: var(--incorrect);
+  border-color: var(--incorrect);
+}
+
+.answer-option.missed {
+  border-color: var(--correct);
+  opacity: 0.7;
+}
+
+/* ── Submit button ── */
+.form-actions {
+  margin-top: 2rem;
